namespace ghidra.app.plugin.core.symboltree;







using docking.widgets.tree;
using docking.widgets.tree.support;
using generic.theme;
using ghidra.app.plugin.core.symboltree.nodes;
using ghidra.app.plugin.core.symboltree.nodes;
using ghidra.app.util;
using ghidra.program.model.symbol;
using resources;

public class SymbolGTree : GTree {

	private GTreeNode armedNode;
	private SymbolInspector symbolInspector;

	public SymbolGTree(GTreeNode root, SymbolTreePlugin plugin) : base(root)
    {
		symbolInspector = new SymbolInspector(plugin.getTool(), this);
		setShowsRootHandles(true);
		setCellRenderer(new SymbolTreeCellRenderer());

		setDragNDropHandler(new SymbolGTreeDragNDropHandler(plugin));

		setAccessibleNamePrefix("Symbol");

		setRootNodeAllowedToCollapse(false);
	}

	// open access
	/* @Override */
	protected void setFilterRestoreState(GTreeState state) {
		base.setFilterRestoreState(state);
	}

	/* @Override */
	public void setNodeEditable(GTreeNode node) {
		armedNode = node;
	}

	/* @Override */
	public bool isPathEditable(TreePath path) {
		bool isArmed = path.getLastPathComponent() == armedNode;
		armedNode = null;
		if (isArmed) {
			return base.isPathEditable(path);
		}
		return false;
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class SymbolTreeCellRenderer : GTreeRenderer {
		public Icon OPEN_FOLDER_GROUP_ICON =
			new GIcon("icon.plugin.symboltree.node.group.folder.open");
		public Icon CLOSED_FOLDER_GROUP_ICON =
			new GIcon("icon.plugin.symboltree.node.group.folder.closed");

		public SymbolTreeCellRenderer() {
			setMinIconWidth(28);
		}

		/* @Override */
		public Component getTreeCellRendererComponent(JTree tree, object value, bool isSelected,
				bool expanded, bool leaf, int row, bool isFocused) {

			JLabel label = (JLabel) base.getTreeCellRendererComponent(tree, value, isSelected,
				expanded, leaf, row, isFocused);

			if (label.getIcon() == null) {
				label.setIcon(expanded ? OPEN_FOLDER_GROUP_ICON : CLOSED_FOLDER_GROUP_ICON);
			}

			if (!isSelected && (value is SymbolNode)) {
				SymbolNode node = (SymbolNode) value;
				Symbol symbol = node.getSymbol();
				Color color = symbolInspector.getColor(symbol);
				label.setForeground(color);
			}

			return label;
		}

		/* @Override */
		protected Icon getNodeIcon(GTreeNode node, bool expanded) {

			Icon icon = base.getNodeIcon(node, expanded);

			if (node is SymbolCategoryNode symbolNode) {
				if (!symbolNode.isEnabled()) {
					return ResourceManager.getDisabledIcon(icon);
				}
			}

			return icon;
		}
	}

	/* @Override */
	public void dispose() {
		base.dispose();
		symbolInspector.dispose();
	}

}
